<?php require 'includes/bootstrap.php';if(me())go(me()['role']==='admin'?'admin/index.php':'dashboard.php');$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{$s=db()->prepare('SELECT * FROM users WHERE email=?');$s->execute([strtolower(trim($_POST['email']??''))]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);unset($u['password_hash']);$_SESSION['user']=$u;go($u['role']==='admin'?'admin/index.php':'dashboard.php');}$err='Email or password is incorrect.';}catch(Throwable $e){$err='Database connection failed. Start MySQL and import database.sql.';}}$pageTitle='Login';require 'includes/header.php';?><div class="form-wrap"><div class="form-card"><span class="eyebrow">WELCOME BACK</span><h1>Sign in</h1><p>Access your student dashboard.</p><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="field"><label>Email address</label><input type="email" name="email" required></div><div class="field"><label>Password</label><input type="password" name="password" required></div><button class="btn primary submit">Sign in</button></form><p>New here? <a href="register.php">Create an account</a></p></div></div><?php require 'includes/footer.php';?>